    (id, assembly_id, item_number, title, category, proposal_reason, status, decided_on, display_order)
  values
    ('d373af15-de13-430b-9e5f-8324a1297238', v_assembly_id, '号未定-1', '令和7年度一般会計繰越明許費繰越計算書', '報告', '令和7年度一般会計予算において翌年度に繰り越した経費について、繰越明許費繰越計算書を議会に報告するもの。', '可決', '2026-06-11', 1),
    ('48ec1027-8bbd-4a39-a9e1-825f1048da4d', v_assembly_id, '号未定-2', '令和7年度広川町一般会計事故繰越し繰越計算書', '報告', '令和7年度一般会計予算の執行において事故繰越しとなった経費について、繰越計算書を議会に報告するもの。', '可決', '2026-06-11', 2),
    ('a159a584-513e-4c49-bd11-eabc10304c6a', v_assembly_id, '号未定-3', '令和7年度広川町下水道事業会計予算繰越計算書', '報告', '令和7年度下水道事業会計予算において翌年度に繰り越した経費について、繰越計算書を議会に報告するもの。', '可決', '2026-06-11', 3),
    ('eca44cd6-7846-44f6-aa13-c6c90af06112', v_assembly_id, '号未定-4', '損害賠償額の決定及び和解(専決処分)', '専決処分', '地方自治法の規定に基づき専決処分した損害賠償額の決定及び和解について、議会の承認を求めるもの。', '可決', '2026-06-11', 4),
    ('d1d1a16b-0519-4d21-b249-62ab1716135f', v_assembly_id, '号未定-5', '町税条例の一部改正', '専決処分', '地方税法等の改正に伴い専決処分した広川町税条例の一部改正について、議会の承認を求めるもの。', '可決', '2026-06-11', 5),
    ('dd17a2c0-cf58-444f-a20e-9dd571f35567', v_assembly_id, '号未定-6', '国民健康保険税条例の一部改正', '専決処分', '国民健康保険税の課税限度額(医療分を1万円引き上げ合計113万円に)及び軽減判定所得基準(5割軽減対象を31万円に、2割軽減対象を57万円に引き上げ)の改正に伴い専決処分した広川町国民健康保険税条例の一部改正について、議会の承認を求めるもの。町全体で519万9千円の負担増となる見込み。江藤議員・竹下議員は、社会保障制度の観点から負担軽減が必要であり限度額を引き上げるべきではないとして反対した。', '可決', '2026-06-11', 6),
    ('2d82b264-6aff-4cbd-9312-29a75622334a', v_assembly_id, '号未定-7', '松川原橋橋梁災害復旧工事請負変更契約の締結', '専決処分', '工事の進捗に伴い、ポンプ施設が工事の支障となること、上水道管の再利用ができないこと、護床ブロックの追加が必要となったことなどにより契約額を変更する必要が生じたため、専決処分した請負変更契約の締結について、議会の承認を求めるもの。', '可決', '2026-06-11', 7),
    ('633d2242-f92c-41be-820a-06e9c16f5e72', v_assembly_id, '号未定-8', '高山橋橋梁災害復旧工事請負変更契約の締結', '専決処分', '工事の進捗に伴い、NTT柱が工事の支障となること、上水道管の再利用が困難であること、上水道管の移設が必要になったことなどにより契約額を変更する必要が生じたため、専決処分した請負変更契約の締結について、議会の承認を求めるもの。', '可決', '2026-06-11', 8),
    ('88031d85-f860-494f-919d-187955a6386d', v_assembly_id, '号未定-9', '農業委員会の委員の選任に対する同意(13件)', '人事', '農業委員会の委員14名の選任について議会の同意を求めるもののうち、同意された13名分。', '可決', '2026-06-11', 9),
    ('d6623696-48c1-4972-992b-b55aa9d28dc5', v_assembly_id, '号未定-10', '農業委員会の委員の選任に対する同意(1件)', '人事', '農業委員会の委員1名の選任について議会の同意を求めるもの。竹下議員より、農業委員会の運営要領に関わる住民説明について会長としての誠実性・透明性に不信感があるとして反対意見が出され、採決の結果、不同意となった。辻議員は選定委員会の公平・公正な審査を経て推薦されており農業委員の経験者でもあるとして賛成した。', '否決', '2026-06-11', 10),
    ('8723b232-08f3-4e40-89f6-dd57a086760f', v_assembly_id, '号未定-11', '水道事業及び下水道事業の設置等に関する条例及び広川町監査委員条例の一部改正', '条例の改正', '水道事業及び下水道事業の設置等に関する条例及び広川町監査委員条例の一部改正について。', '可決', '2026-06-11', 11),
    ('6c12cba0-eeba-441b-b0c8-1e3055aa1b7d', v_assembly_id, '号未定-12', '移住定住促進センター兼滞在交流施設の設置及び管理に関する条例の制定', '条例の制定', '移住定住促進センター兼滞在交流施設の設置及び管理に関する条例を制定するもの。', '可決', '2026-06-11', 12),
    ('8b7a7957-f424-47d6-9e82-03765489f7f2', v_assembly_id, '号未定-13', '職員の特殊勤務手当に関する条例の一部改正', '条例の改正', '職員の特殊勤務手当に関する条例の一部改正について。', '可決', '2026-06-11', 13),
    ('ab7740ac-9e3f-4346-a5b8-4028421e174e', v_assembly_id, '号未定-14', '小中学校学習者用端末等購入に係る契約の締結', '契約の締結', '児童生徒が使用するタブレット端末が更新時期を迎えるため、1,749台のタブレット端末を購入し入れ替えを行うもの。契約額は8,540万円。', '可決', '2026-06-11', 14),
    ('346dd075-6038-4352-bb19-ac2ea98f1354', v_assembly_id, '号未定-15', '指定ごみ袋購入に係る契約の締結', '契約の締結', '指定ごみ袋77万枚の購入に係る契約を締結するもの。購入単価は大袋1.48倍、小袋1.63倍に値上がりした。町民の購入価格については値上げを考えていないとの答弁があった。', '可決', '2026-06-11', 15),
    ('3d642ef7-ec40-4732-b984-92d360e580ff', v_assembly_id, '号未定-16', '中広川小学校LED化工事請負契約の締結', '契約の締結', '中広川小学校の普通教室・特別教室など全てをLED化する工事請負契約を締結するもの。契約額869万円。授業に影響がないよう夏休みを中心に工事を行う。', '可決', '2026-06-11', 16),
    ('0f190d39-78d6-48f4-b582-52ffcaeb0cc8', v_assembly_id, '号未定-17', '損害賠償額の決定及び和解', '契約の締結', '損害賠償額の決定及び和解について、議会の議決を求めるもの(専決処分によらないもの)。', '可決', '2026-06-11', 17),
    ('4972aeb7-2eef-4804-9d8c-9139d36380fe', v_assembly_id, '議案第37号', '令和8年度広川町一般会計補正予算(第1号)について', '補正予算', '歳入歳出予算の総額に歳入歳出それぞれ5,319万9千円を追加し、歳入歳出予算の総額を100億4,929万円とするもの。主な内容は、こどもまんなかアプリケーション作成支援委託料や位置情報システム整備委託料等に係る債務負担行為の追加、上広川小学校建設基本構想・基本計画策定支援業務に係る債務負担行為の追加、緊急自然災害防止対策事業(道路防災・河川・農林業施設防災・公園施設長寿命化)に係る地方債の追加など。令和8年6月4日提出。', '可決', '2026-06-11', 18),
    ('62f0efe5-7886-40b7-b2c0-279927efd074', v_assembly_id, '議案第38号', '令和8年度広川町国民健康保険特別会計補正予算(第1号)について', '補正予算', '歳入歳出予算の総額に歳入歳出それぞれ499万8千円を追加し、歳入歳出予算の総額を21億9,523万9千円とするもの。国民健康保険担当職員人件費(補助的会計年度任用職員の増員等)に係る一般会計繰入金の増額が主な内容。令和8年6月4日提出。', '可決', '2026-06-11', 19);
