  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('b9fc4b7e-5fd9-498d-aab6-6033ea16bba7', '1ffaef59-1dfd-4f50-ad4d-8170307d717a', 'ふるさと納税の今後の対策', '議会だよりに具体的な質疑応答内容の記載なし。件名のみ確認。', NULL, 1),
    ('b5739e70-caff-455f-b258-b8515e0e58ee', '1ffaef59-1dfd-4f50-ad4d-8170307d717a', '一般国道3号広川八女バイパスの進捗状況と町の取り組み', '辻議員が福岡国道事務所との協議状況を質問。町長は、令和8年度から本格的な用地買収に着手する計画で、商業施設の立地に関するサウンディング型調査(民間事業者との対話を通じた意見収集)を実施したと説明。調査結果では4haの商業施設をバイパス沿線にとの案が示されており、辻議員はその実現にはバイパスへの乗り入れ口が必要ではないかと質問。町長は、乗り入れ口の新設については福岡国道事務所と意見交換をしており、実現可能性を探りながら協議を継続していくと答弁。買い物施設が乏しい上広川校区への接続に活かしてほしいとの要望に対し、町長は商業施設の誘致に前向きに取り組み、乗り入れ口については地元の声として届けていくと述べた。工事は長延地区の寺山堤より東西に進めていく予定。', NULL, 2),
    ('f1ffcc03-fdb0-4e50-9f27-05b1e918b92c', 'e58f67e7-f258-44a5-b055-dafa965dd78d', '空き家対策', '空き家対策について、これまでの成果と現状、特定空き家指定の考えを質問。町からは、指定の実績はないが、これまでの取組みには一定の成果があり、今後も町財政への影響も鑑みながら慎重に取り組んでいくとの答弁があった。', NULL, 1),
    ('3673b061-3d29-46d1-a8f3-a79aa6a5a769', 'e58f67e7-f258-44a5-b055-dafa965dd78d', '道路交通法改正に伴う交通安全の考え', '改正道路交通法を踏まえ、自転車利用の多い中学生への交通安全指導について質問。教育長は、警察庁・文部科学省からの通知を踏まえ徹底指導を行っており、今回の法改正を踏まえてより実践的な指導を図っていきたいと答弁。また、通学路の標識やミラーの適正設置等の確認について、子供目線での配置になっているか質問したところ、教育長は交通安全推進会議で調査・確認をしているが、会議に出席しているのは大人目線での調査であると述べた。', NULL, 2),
    ('2e73c113-baf4-499d-b5e2-d70e57a6d679', 'c507703f-236d-4355-82fb-fd837c201a79', '高齢者の自動車運転免許の返納', '議会だよりに具体的な質疑応答内容の記載なし。件名のみ確認。', NULL, 1),
    ('171636f9-9b19-4c5b-b27b-55e119437839', 'c507703f-236d-4355-82fb-fd837c201a79', '圃場整備された農地に日照の問題が生じている件', '圃場整備された第一種農地で日照の問題が生じている件について質問。議会だよりには写真キャプションのみで、具体的な質疑応答内容の記載はない。', NULL, 2),
    ('ab6c1ae1-0958-4799-9012-085a468c8962', 'c507703f-236d-4355-82fb-fd837c201a79', '特定の国会議員の支援', '議会だよりに具体的な質疑応答内容の記載なし。件名のみ確認。', NULL, 3),
    ('4479bc15-1441-4ea5-a750-135e75fc08d3', 'a9a47f27-061f-4d48-8a8a-93c13eb4d44e', '町民の移動手段(地域交通)の現状と今後の課題', '地域交通は町民にとって非常に重要であり、免許証返納後の移動手段に不安を感じる住民が多いと指摘。2040年問題(全国的に3人に1人が65歳以上になるとされる)を踏まえ、地域交通の現状と今後の課題を質問。町長は、高齢者の免許返納に伴い移動手段の確保が課題であり、町民アンケートでも公共交通の利便性への不満が示されていると答弁。下田議員は、デマンドタクシーの定義や利用方法を広報で特集を組むなどして町民の理解を深めるべきと提案し、町長は指摘の通り重要であり、広報ヒロカワなどで今後丁寧に知らせていくと答弁。今後は既存事業者との連携やAI活用を検討してほしいとの要望に対し、町長は公共交通を「生活インフラ」と位置付け、持続可能な地域ネットワーク構築に意欲的に取り組んでいくと述べた。', NULL, 1),
    ('52dba9bd-894e-4c15-a467-6147243977ed', 'b4046b1f-a13a-437b-b85b-fe7b3c52f693', '令和8年度の職員雇用状況', '令和8年度の職員雇用状況について質問。町長は、当初は充足してスタートしたが、その後3名の退職者が出たと説明。給与水準については国の制度に準処し均衡の取れた水準にあると認識していると答弁。職員の定着・育成については、広川町人材育成基本方針に基づき研修を実施するとともに、今後は人事評価制度を活用し、成果を上げている職員が相応の処遇を受けられる仕組みを検討しているとした。', NULL, 1),
    ('2b93dfd9-501c-40cd-a59e-05b6f0255743', 'b4046b1f-a13a-437b-b85b-fe7b3c52f693', '歴史教育への積極的な取り組み', '故郷の歴史を学ぶことは子どもたちの郷土への誇りや郷土愛を育てる上で意義深いとの回答を得た。筑紫の君・磐井の乱から1500年の節目を活かし、郷土史会等の民間活用を積極的に行ったらどうかとの問いには、各学校のカリキュラムや年間指導計画を策定する段階から調整して取り組みたいとの答弁があった。', NULL, 2),
    ('0d0fdf89-7e0b-4998-ad53-caa12d953455', 'b4046b1f-a13a-437b-b85b-fe7b3c52f693', '選挙啓発の取り組み', '議会だよりに具体的な質疑応答内容の記載なし。件名のみ確認。', NULL, 3),
    ('701f2d75-9b9a-43bf-8596-382a35a7ccef', 'f214da49-1660-4851-a1f1-2c197aed0a01', '中東情勢がもたらす物価高、資材不足の影響と対応', 'イラン戦争によりホルムズ海峡が事実上封鎖され、経済と暮らしに重大な影響が出ているとして、町内の実態を把握しているか質問。町長は、JAからは一部資材の生産が止まっていると聞いており、商工会には数件の相談があり、個人事業主などからは「資材が入らない」「単価が上がった」「見積もりに支障が出ている」と聞いていると答弁。医療現場からは特段困っているとの声は聞いていないとした。江藤議員は、コロナの時より国の対応が遅く、影響を受ける業種も非常に多く、先行きが全く見えない死活問題であるとして、町としてできることはないか質問。町長は、現場と緊密な情報共有に努め実情を的確に把握し、国・県の支援策を注視しながら町独自の支援策を機動的に実施できるよう準備しておくと答弁した。', NULL, 1),
    ('3f501a3d-f8ea-4f17-b862-63f0bf2568f6', 'f214da49-1660-4851-a1f1-2c197aed0a01', '佐賀空港へのオスプレイ配備と町民の安全確保', '佐賀駐屯地に配備されたオスプレイに関連して、町民生活の安全・安心への対応について質問。圧迫感や危険性を感じる状態ではないが、飛行についての情報発信は検討するとの答弁を得た。', NULL, 2),
    ('76add885-99bc-4274-9de0-7c7494b4a293', '56a2dccb-cfcd-4ee2-bf55-d7e86380b966', '広川町の公民館制度を見直し、公民館活動の進め方を再考する考え', '公民館制度を見直し、中央公民館を中心とした校区分館制にできないか質問。町長は、持続可能な公民館活動の在り方について研究すると答弁。地区公民館を構成する子供会・少年団・壮年会・シニアクラブなどの活動状況について、地域差はあるが子供会は規模縮小、少年団は数が減少していると説明。常時活動の困難性や継続性に課題があるとして、子供会や少年団といった年齢的な枠組みは撤廃できないか質問したところ、町長はほかの自治体でも年齢にこだわらない例が見られ可能だと考えると答弁。指導員が常駐する校区分館のような在り方が必要ではないかとの問いには、効率的かつ持続的な地域活動を模索する視点だと認識しているが、既存の分館の役割分担や機能をどうするかなど課題があり、今後地域の声を聴きながら研究を進めていくと答弁した。', NULL, 1),
    ('99bfc968-883a-41f3-aadd-be32a023021d', '56a2dccb-cfcd-4ee2-bf55-d7e86380b966', 'プール指導の民間委託の報告', '水泳授業の民間委託について尋ね、判断の客観性と継続性について教育委員会で十分考慮すると回答を得た。', NULL, 2),
    ('0073667e-446d-4e28-be5f-511e793edc34', '56a2dccb-cfcd-4ee2-bf55-d7e86380b966', '上広川地区の振興策として、スーパーやコンビニエンスストアなどの誘致', '上広川地区の買い物事情の改善についてはコンビニより調査中の商業施設を推進すると答弁を得た。', NULL, 3);
