-- purpose: 令和8年第2回(6月)定例会のデータを新規投入する
-- affected: assemblies, agenda_items, general_questions, question_topics
-- notes: 会議録(逐語録)が本執筆時点(令和8年8月)でまだ公開されていないため、
--        議案(agenda_items)の内容は町公式の「議会だより第102号」を主な情報源とした。
--        一般会計補正予算(第1号)=議案第37号、国民健康保険特別会計補正予算(第1号)=議案第38号は
--        町が公開する正式な議案書PDF(R8ippann1gou.pdf, R8kokuho1gou.pdf)の記載内容に基づく。
--        それ以外の29件(報告3件・専決処分5件・人事14件・条例改正3件・契約締結4件)は、
--        正式な議案番号が会議録の公開まで確認できないため、item_numberは"号未定-N"の仮ラベルとし、
--        個々の農業委員選任(14件)は議会だよりの記載単位(13件同意分・1件不同意分)のまま
--        2件のagenda_itemsとして集約登録した(合計19件)。会議録公開後に正式な議案番号・
--        個別内容への更新を要する。
--        一般質問(general_questions)も同じ理由で、会議録ではなく議会だより第102号(8-11ページ)を
--        情報源としている。竹下英治議員の3論点、辻満晴議員の「ふるさと納税」論点は、
--        議会だよりに具体的な質疑応答の記載がなかったため、件名のみ登録し内容は空欄に近い状態とした。
--        council_membersは既存レコード(氏名で解決)を利用し、新規作成は行わない。

do $$
declare
  v_assembly_id uuid := '79063e2e-6bc6-45f8-aa98-74799b785b49';
begin

  -- 冪等ガード: 既に投入済みなら何もしない
  if exists (
    select 1 from public.assemblies
    where fiscal_year = 2026
      and session_type = '定例会'
      and session_number = 2
  ) then
    raise notice '既に投入済みのためスキップします';
    return;
  end if;


  -- council_members: 本番に未登録の2名を追加(氏名で存在確認、seat_numberは公式資料未確認のためNULL)
  select '3b4065b5-3f20-48c7-b44e-4d85e75a450c', '辻満晴', NULL, '一般'
  where not exists (select 1 from public.council_members where name = '辻満晴');

  select '79408ede-bec4-4db9-b4c6-3c51d1ea527b', '梶原一美', NULL, '一般'
  where not exists (select 1 from public.council_members where name = '梶原一美');

  -- agenda_items: 報告・専決処分・人事・条例改正・契約締結(議案番号未確定、"号未定-N"の仮ラベル)

  -- general_questions: council_member_idは氏名で既存レコードを解決する
  select '1ffaef59-1dfd-4f50-ad4d-8170307d717a', v_assembly_id, cm.id, 1, 'ふるさと納税の今後の対策、一般国道3号広川八女バイパスの進捗状況と町の取り組み'
  from public.council_members cm where cm.name = '辻満晴';

  select 'e58f67e7-f258-44a5-b055-dafa965dd78d', v_assembly_id, cm.id, 2, '空き家対策、道路交通法改正に伴う交通安全の考え'
  from public.council_members cm where cm.name = '池尻浩一';

  select 'c507703f-236d-4355-82fb-fd837c201a79', v_assembly_id, cm.id, 3, '高齢者の自動車運転免許の返納、圃場整備された農地の日照問題、特定の国会議員の支援'
  from public.council_members cm where cm.name = '竹下英治';

  select 'a9a47f27-061f-4d48-8a8a-93c13eb4d44e', v_assembly_id, cm.id, 4, '町民の移動手段(地域交通)の現状と今後の課題'
  from public.council_members cm where cm.name = '下田めぐみ';

  select 'b4046b1f-a13a-437b-b85b-fe7b3c52f693', v_assembly_id, cm.id, 5, '令和8年度の職員雇用状況、歴史教育への積極的な取り組み、選挙啓発の取り組み'
  from public.council_members cm where cm.name = '藤島玄稔';

  select 'f214da49-1660-4851-a1f1-2c197aed0a01', v_assembly_id, cm.id, 6, '中東情勢がもたらす物価高・資材不足の影響と対応、佐賀空港へのオスプレイ配備と町民の安全確保'
  from public.council_members cm where cm.name = '江藤美代子';

  select '56a2dccb-cfcd-4ee2-bf55-d7e86380b966', v_assembly_id, cm.id, 7, '広川町の公民館制度の見直し、プール指導の民間委託、上広川地区の振興策'
  from public.council_members cm where cm.name = '梶原一美';

  -- question_topics: 議会だより第102号(8-11ページ)の内容に基づく

end $$;
